import{_ as t,l as r,o as a,c as l,v as o,p as s,x as d,d as n,i,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"调用约定与栈","description":"","frontmatter":{"title":"调用约定与栈","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/calling-convention-stack.md","filePath":"cs/calling-convention-stack.md","lastUpdated":1789023840000}'),h={name:"cs/calling-convention-stack.md"};function E(A,e,_,B,m,u){const c=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="调用约定与栈" tabindex="-1">调用约定与栈 <a class="header-anchor" href="#调用约定与栈" aria-label="Permalink to &quot;调用约定与栈&quot;">​</a></h1><div class="epigraph"><p>ISA 只保证 `jal` 把返回地址放进 `rd`；谁保存哪些寄存器、参数放哪、栈向哪长，是软件与硬件共同遵守的 ABI。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；RISC-V Calling Convention 整理</footer></div><p>上一课<a href="/cs/bus-mmio">总线与 MMIO</a>让硬件能执行任意指令序列。本课不重画 FSM 状态，也不从操作系统进程映像另起。缺口是：过程调用在 ISA 里只有 <code>jal</code>/<code>jalr</code> 与一堆通用寄存器。没有约定，调用者与被调用者会互相覆盖 <code>x</code> 寄存器，返回地址也会丢。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RV32I 能跳、能存。缺口是 <strong>ABI</strong>：参数进 <code>a0</code>–<code>a7</code>（<code>x10</code>–<code>x17</code>），返回值 <code>a0</code>/<code>a1</code>；<code>ra</code> 存返回地址；栈由 <code>sp</code> 指向，向低地址增长；调用者保存与被调用者保存寄存器划分（caller/callee saved）。栈帧：保存 <code>ra</code>、<code>s</code> 寄存器、局部变量、溢出的参数。</p><p>硬件不强制这些，编译器与手写汇编必须一致。叶子函数可以不建帧，但不得破坏 callee-saved。</p><h3 id="栈不是「栈-adt-课」" tabindex="-1">栈不是「栈 ADT 课」 <a class="header-anchor" href="#栈不是「栈-adt-课」" aria-label="Permalink to &quot;栈不是「栈 ADT 课」&quot;">​</a></h3><p>这里的栈是内存中由 <code>sp</code> 界定的连续区，用 <code>sw</code>/<code>lw</code> 访问。数据结构课的栈抽象会后出现；本课是组成层的调用栈。不要把 Java 操作数栈或 x87 浮点栈混进来。</p><p><span class="marginnote">Patterson/Hennessy 用 RISC-V 调用例子画栈帧。官方 psABI 规定寄存器角色。本课不把完整 ELF 重定位提前。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>jal rd, offset</code> 写 <code>rd=PC+4</code> 并跳；惯例 <code>rd=ra</code>。被调用者：<code>addi sp,sp,-N</code>，存 <code>ra</code> 与需保存的 <code>s</code> 寄存器，用完 <code>lw</code> 恢复，<code>addi sp,sp,N</code>，<code>jalr x0,0(ra)</code>。递归每次新帧，否则 <code>ra</code> 被覆盖。</p>',11)),(a(),s(p,null,{default:d(()=>[i(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20JAL%5B%22jal%20%E5%86%99%20ra%22%5D%20--%3E%20FRAME%5B%22%E6%A0%88%E5%B8%A7%EF%BC%9Ara%20%E4%B8%8E%20s%20%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20FRAME%20--%3E%20BODY%5B%22%E8%BF%87%E7%A8%8B%E4%BD%93%22%5D%0A%20%20BODY%20--%3E%20RET%5B%22%E6%81%A2%E5%A4%8D%20sp%20%E4%B8%8E%20jalr%22%5D%0A%20%20RET%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BC%82%E5%B8%B8%E4%B9%9F%E6%94%B9%20PC%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>叶子过程可把 <code>ra</code> 留在寄存器。非叶子必须把 <code>ra</code> 入栈再 <code>jal</code> 出去。变长参数与栈上传参是 ABI 细节，本课点到：寄存器不够则放在 <code>sp</code> 之上的约定槽。栈溢出是软件错误，硬件只在访问未映射页时异常——页表很后。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲异常帧、不讲信号处理器。不把线程的多栈、协程提前。尾调用优化可省略帧，但是约定下的优化，不是硬件指令。</p><p>后课默认：过程调用遵守 RISC-V 整数 ABI；栈向低地址长。异常与中断也会改 PC，但不是 <code>jal</code>，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>jal</code> 只提供返回地址机制；ABI 规定寄存器与栈帧。</li><li>caller/callee saved 防止互相覆盖。</li><li>递归必须入栈 <code>ra</code>。异常入口是另一条改 PC 的路。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V psABI。</li></ul>',7))])}const I=t(h,[["render",E]]);export{f as __pageData,I as default};
